SC="sc s08-fast"
check "StorageClass s08-fast: local-path, Delete, WaitForFirstConsumer, expansion allowed, not default" '[ "$(jp $SC "{.provisioner}:{.reclaimPolicy}:{.volumeBindingMode}:{.allowVolumeExpansion}")" = rancher.io/local-path:Delete:WaitForFirstConsumer:true ] && [ "$(jp $SC "{.metadata.annotations.storageclass\.kubernetes\.io/is-default-class}")" != true ]'
check "headless Service kv on port 6379" '[ "$(jp svc kv -n s08-kv "{.spec.clusterIP}:{.spec.ports[0].port}")" = None:6379 ]'
check "StatefulSet kv uses serviceName kv and has 2 ready replicas" '[ "$(jp sts kv -n s08-kv "{.spec.serviceName}:{.spec.replicas}")" = kv:2 ] && kubectl -n s08-kv rollout status sts/kv --timeout=90s && [ "$(jp sts kv -n s08-kv "{.status.readyReplicas}")" = 2 ]'
check "claim template data: ReadWriteOnce, 64Mi, class s08-fast, mounted at /data" '[ "$(jp sts kv -n s08-kv "{.spec.volumeClaimTemplates[0].metadata.name}:{.spec.volumeClaimTemplates[0].spec.accessModes[0]}:{.spec.volumeClaimTemplates[0].spec.resources.requests.storage}:{.spec.volumeClaimTemplates[0].spec.storageClassName}")" = data:ReadWriteOnce:64Mi:s08-fast ] && [ "$(jp sts kv -n s08-kv "{.spec.template.spec.containers[0].volumeMounts[?(@.name==\"data\")].mountPath}")" = /data ]'
check "PVCs data-kv-0 and data-kv-1 are Bound via s08-fast" 'for i in 0 1; do [ "$(jp pvc data-kv-$i -n s08-kv "{.status.phase}:{.spec.storageClassName}")" = Bound:s08-fast ] || exit 1; done'
check "redis in kv-0 runs with appendonly and its data dir on the PVC" '[ "$(kubectl -n s08-kv exec kv-0 -- redis-cli config get appendonly | tail -1)" = yes ] && kubectl -n s08-kv exec kv-0 -- sh -c "grep -q \" /data \" /proc/mounts"'
check "key owner=cka in kv-0 survived a Pod recreation" '[ "$(kubectl -n s08-kv exec kv-0 -- redis-cli get owner)" = cka ] && p=$(date -d "$(jp pod kv-0 -n s08-kv "{.metadata.creationTimestamp}")" +%s) && c=$(date -d "$(jp pvc data-kv-0 -n s08-kv "{.metadata.creationTimestamp}")" +%s) && [ $((p-c)) -gt 5 ]'
guard "local-path is still a StorageClass" 'kubectl get sc local-path'
